import java.util.*;
import java.io.*;

public class Main {
    static class Edge {
        int to, capacity, cost, rev;
        Edge(int to, int capacity, int cost, int rev) {
            this.to = to;
            this.capacity = capacity;
            this.cost = cost;
            this.rev = rev;
        }
    }

    static class CostFlow {
        static final int MAXV = 5010;
        int V;
        List<Edge>[] graph = new ArrayList[MAXV];
        int[] potential = new int[MAXV];
        int[] dist = new int[MAXV];
        int[] prevVertex = new int[MAXV];
        int[] prevEdge = new int[MAXV];

        @SuppressWarnings("unchecked")
        void init(int n) {
            V = n;
            for (int i = 0; i < V; i++) {
                graph[i] = new ArrayList<>();
            }
        }

        void addEdge(int from, int to, int cap, int cst) {
            graph[from].add(new Edge(to, cap, cst, graph[to].size()));
            graph[to].add(new Edge(from, 0, -cst, graph[from].size() - 1));
        }

        int minCostFlow(int s, int t, int flow) {
            int res = 0;
            Arrays.fill(potential, 0);
            while (flow > 0) {
                PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
                Arrays.fill(dist, Integer.MAX_VALUE);
                dist[s] = 0;
                pq.offer(new int[]{0, s});
                while (!pq.isEmpty()) {
                    int[] cur = pq.poll();
                    int d = cur[0], v = cur[1];
                    if (dist[v] < d) continue;
                    for (int i = 0; i < graph[v].size(); i++) {
                        Edge e = graph[v].get(i);
                        if (e.capacity > 0 && dist[e.to] > dist[v] + e.cost + potential[v] - potential[e.to]) {
                            dist[e.to] = dist[v] + e.cost + potential[v] - potential[e.to];
                            prevVertex[e.to] = v;
                            prevEdge[e.to] = i;
                            pq.offer(new int[]{dist[e.to], e.to});
                        }
                    }
                }
                if (dist[t] == Integer.MAX_VALUE) return -1;
                for (int v = 0; v < V; v++) {
                    potential[v] += dist[v];
                }
                int addFlow = flow;
                for (int v = t; v != s; v = prevVertex[v]) {
                    addFlow = Math.min(addFlow, graph[prevVertex[v]].get(prevEdge[v]).capacity);
                }
                flow -= addFlow;
                res += addFlow * potential[t];
                for (int v = t; v != s; v = prevVertex[v]) {
                    Edge e = graph[prevVertex[v]].get(prevEdge[v]);
                    e.capacity -= addFlow;
                    graph[v].get(e.rev).capacity += addFlow;
                }
            }
            return res;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());
        int d = Integer.parseInt(st.nextToken());

        int[] a = new int[50];
        int[] countArr = new int[50];
        List<Integer>[] adj = new ArrayList[50];
        for (int i = 0; i < 50; i++) {
            adj[i] = new ArrayList<>();
        }

        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < k; i++) {
            a[i] = Integer.parseInt(st.nextToken());
            countArr[a[i] - 1]++;
        }

        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            int x = Integer.parseInt(st.nextToken()) - 1;
            int y = Integer.parseInt(st.nextToken()) - 1;
            adj[x].add(y);
            adj[y].add(x);
        }

        int T = 100;
        CostFlow flowSolver = new CostFlow();
        flowSolver.init(n * T + 2);
        int s = n * T;
        int t = n * T + 1;

        for (int i = 0; i < n; i++) {
            flowSolver.addEdge(s, i, countArr[i], 0);
        }
        for (int i = 0; i < T; i++) {
            flowSolver.addEdge(i * n, t, k, c * i);
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < T - 1; j++) {
                flowSolver.addEdge(j * n + i, (j + 1) * n + i, k, 0);
            }
            for (int to : adj[i]) {
                for (int j = 0; j < T - 1; j++) {
                    for (int u = 0; u < k; u++) {
                        int cost = (u + 1) * (u + 1) * d - u * u * d;
                        flowSolver.addEdge(j * n + i, (j + 1) * n + to, 1, cost);
                    }
                }
            }
        }
        System.out.println(flowSolver.minCostFlow(s, t, k));
    }
}
